head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst20100";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst20100.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $("#ipt_digitalIsuSrtNm").bind("change", function() {
                $c.util.getComponent('ipt_digitalIsuSrtCd').setValue("");
        });
        $("#ipt_listApplntIsurNm").bind("change", function() {
                $c.util.getComponent('ipt_listApplntIsurCd').setValue("");
        });
        $("#ipt_reportNm").bind("change", function() {
                $c.util.getComponent('ipt_reportCd').setValue("");
        });
        $("#ipt_digitalIsuSrtNm").bind("keypress", async function(e) {
                if (e.keyCode === 13) {
                    if ($c.util.getComponent('ipt_digitalIsuSrtNm').getValue() !== $c.util.getComponent('ipt_digitalIsuSrtCd').getValue()) {
                        $c.util.getComponent('ipt_digitalIsuSrtCd').setValue("");
                    }
                    await scwin.fnSearchInit();
                }
        });
        $("#ipt_listApplntIsurNm").bind("keypress", async function(e) {
                if (e.keyCode === 13) {
                    if ($c.util.getComponent('ipt_listApplntIsurNm').getValue() !== $c.util.getComponent('ipt_listApplntIsurCd').getValue()) {
                        $c.util.getComponent('ipt_listApplntIsurCd').setValue("");
                    }
                    await scwin.fnSearchInit();
                }
        });
        $("#ipt_reportNm").bind("keypress", async function(e) {
                if (e.keyCode === 13) {
                    if ($c.util.getComponent('ipt_reportNm').getValue() !== $c.util.getComponent('ipt_reportTmp').getValue()) {
                        $c.util.getComponent('ipt_reportCd').setValue("");
                    }
                    await scwin.fnSearchInit();
                }
        });
        // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
        //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
        //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "1 ') */
        await scwin.fnSearchInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20100.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

/**
 * @method
 * @name btn_pd_1w_onclick
 * @description 「1주」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1w_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addDate(to, -7); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst20100.pd_1w' }); } };

